AssistantMessageToolRequest(name='create', tool_call_id='function-call-37f5920d-6b3b-4faa-81a4-f9452beabb9e', arguments={'file_text': "document.addEventListener('DOMContentLoaded', () => {
    const form = document.getElementById('contact-form');
    const statusMessage = document.getElementById('status-message');

    form.addEventListener('submit', (event) => {
        event.preventDefault();

        // Clear previous errors
        document.querySelectorAll('.error-message').forEach(el => el.remove());
        document.querySelectorAll('input').forEach(input => {
            input.removeAttribute('aria-invalid');
            input.style.borderColor = '';
        });

        const formData = new FormData(form);
        const data = Object.fromEntries(formData.entries());

        // Simple validation
        let firstInvalidField = null;

        if (!data['full-name'] || data['full-name'].trim() === '') {
            showError('full-name', 'Full name is required.');
            if (!firstInvalidField) firstInvalidField = document.getElementById('full-name');
        }

        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!data['email'] || !emailRegex.test(data['email'])) {
            showError('email', 'Please enter a valid email address.');
            if (!firstInvalidField) firstInvalidField = document.getElementById('email');
        }

        if (firstInvalidField) {
            firstInvalidField.focus();
            statusMessage.textContent = 'Please correct the errors above.';
            statusMessage.style.color = 'var(--error-color)';
            return;
        }

        // Simulate submission
        statusMessage.textContent = 'Submitting...';
        statusMessage.style.color = 'var(--text-color)';

        setTimeout(() => {
            statusMessage.textContent = 'Thank you! Your support request has been sent.';
            statusMessage.style.color = 'var(--primary-color)';
            form.reset();
        }, 1500);
    });

    function showError(fieldId, message) {
        const field = document.getElementById(fieldId);
        field.setAttribute('aria-invalid', 'true');
        field.style.borderColor = 'var(--error-color)';

        const errorElement = document.createElement('p');
        errorElement.className = 'error-message';
        errorElement.id = `${fieldId}-error`;
        errorElement.textContent = `Error: ${message}`;

        // Link error message to input
        const currentDescribedBy = field.getAttribute('aria-describedby') || '';
        if (!currentDescribedBy.includes(`${fieldId}-error`)) {
            field.setAttribute('aria-describedby', `${currentDescribedBy} ${fieldId}-error`.trim());
        }

        field.parentNode.appendChild(errorElement);
    }
});
