            statusMessage.textContent = 'Please correct the errors above.';
            statusMessage.style.color = 'var(--error-color)';
            return;
        }

        // Simulate submission
        statusMessage.textContent = 'Submitting...';
        statusMessage.style.color = 'var(--text-color)';

        setTimeout(() => {
            statusMessage.textContent = 'Thank you! Your support request has been sent.';
            statusMessage.style.color = 'var(--primary-color)';
            form.reset();
        }, 1500);
    });

    function showError(fieldId, message) {
        const field = document.getElementById(fieldId);
        field.setAttribute('aria-invalid', 'true');
        field.style.borderColor = 'var(--error-color)';

        const errorElement = document.createElement('p');
